#include <iostream>
#include <vector>

void printVector(const std::vector<int>& vec, const char* name) {
    std::cout << name << " (size " << vec.size() << "): ";
    for (int val : vec) {
        std::cout << val << " ";
    }
    std::cout << "\n";
}

int main() {
    // C++11 list initialization
    std::vector<int> vec1{10, 20, 30};
    std::vector<int> vec2{10, 20, 30};

    printVector(vec1, "vec1");
    printVector(vec2, "vec2");

    if (vec1 == vec2) {
        std::cout << "vec1 and vec2 are equal\n";
    }

    // Append element dynamically
    vec1.push_back(40);
    std::cout << "After push_back(40):\n";
    printVector(vec1, "vec1");

    if (vec1 != vec2) {
        std::cout << "vec1 and vec2 are now not equal\n";
    }

    // Copy assignment
    vec2 = vec1;
    std::cout << "After vec2 = vec1:\n";
    printVector(vec2, "vec2");

    return 0;
}

#include <iostream>
#include <vector>
#include <stdexcept>

int main() {
    std::vector<int> values{10, 20, 30};

    // Valid access using [] and at()
    values[1] = 25; // modify via lvalue
    std::cout << "values[1] = " << values.at(1) << "\n";

    // Safe access with try-catch and at()
    try {
        std::cout << "Attempting to access index 5...\n";
        int invalidItem = values.at(5); // Out of bounds
        std::cout << "Item: " << invalidItem << "\n"; // Never reached
    } catch (const std::out_of_range& ex) {
        std::cout << "Caught std::out_of_range: " << ex.what() << "\n";
    }

    // Program continues normally
    std::cout << "Program recovered and resumes execution successfully.\n";
    return 0;
}
